window.GuanwuKnowledge=(()=>{
 const data=GUANWU_KNOWLEDGE,core=GuanwuKnowledgeCore;
 const e=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const get=id=>data.objects.find(o=>o.id===id),src=id=>data.sources.find(s=>s.id===id);
 const fieldLabels={title:'整理名称',originalName:'馆方原名',institution:'收藏机构',accession:'官方藏品编号',period:'年代归类',dateOriginal:'馆方原始年代',medium:'材质原文',dimensions:'尺寸',technique:'工艺与纹饰',creditLine:'馆方入藏说明',use:'用途记载',provenance:'出土或流传信息'};
 let filters={query:'',institution:'',period:'',objectType:''},selected=[],controller=null;
 try{const saved=JSON.parse(localStorage.getItem('guanwu-tea-compare')||'[]');if(Array.isArray(saved))selected=[...new Set(saved)].filter(id=>get(id)).slice(0,2)}catch{}
 const links=ids=>ids.map(id=>{const s=src(id);return s?`<a href="${e(s.url)}" target="_blank" rel="noopener">${e(s.title)} ↗</a>`:''}).join('');
 function image(o,extra=''){return o.image.src?`<img src="${e(o.image.src)}" alt="${e(o.title)}，馆藏编号${e(o.fields.accession.value)}" ${extra}>`:`<div class="knowledge-no-photo"><span>藏品档案</span><b>${e(o.objectType)}</b><small>原图请见馆方页面 ↗</small></div>`}
 function card(o){return `<article class="knowledge-card"><a class="knowledge-card-photo" href="#object/${o.id}">${image(o,'loading="lazy"')}<span>${e(o.period)} · ${e(o.objectType)}</span></a><div><small>${e(o.institution)}</small><h3><a href="#object/${o.id}">${e(o.title)}</a></h3><p>${e(o.summary)}</p><footer><span>${e(o.fields.accession.value||'原站未提供编号')}</span><button data-knowledge-pick="${o.id}" class="text-link" aria-pressed="${selected.includes(o.id)}">${selected.includes(o.id)?'✓ 已选':'＋ 对看'}</button></footer></div></article>`}
 function teaser(){return `<section class="knowledge-teaser"><div><div class="eyebrow">BEYOND ONE MUSEUM · 文化知识助手</div><h2>一盏茶，<br>串起几座博物馆。</h2><p>宋人为什么偏爱黑盏？紫砂和瓷器有什么不同？<br>把器物放回生活，每一个解释都留有出处。</p><a class="solid-btn" href="#knowledge">走进茶器专题 ↗</a></div><a href="#knowledge" aria-label="走进茶器专题">${image(get('tea-met-48117'),'loading="lazy"')}<span>建窑兔毫茶盏 · The Met · CC0</span></a></section>`}
 function bar(){return `<div class="knowledge-compare-bar" role="status"><span>${selected.length?selected.map(id=>e(get(id).title)).join(' × '):'选两件茶器，把差别看清楚。'}</span><a class="${selected.length===2?'solid-btn':'outline-btn'}" href="#knowledge-compare">双件对看 ${selected.length}/2 ↗</a>${selected.length?'<button class="text-link" data-knowledge-clear>清空</button>':''}</div>`}
 function result(){const found=core.search(data,{...filters,limit:30});return `<p class="knowledge-count" role="status">找到 <strong>${found.objects.length}</strong> 件茶器 <span>已选条件只筛选藏品；背景资料单独关联。</span></p>${found.objects.length?`<div class="knowledge-grid">${found.objects.map(card).join('')}</div>`:'<div class="soft-empty">首批资料里没有符合这些条件的茶器。可以清空筛选，或查阅下方专题背景。<button data-knowledge-reset class="text-link">清空筛选</button></div>'}${bar()}`}
 function askPanel(question=''){return `<section class="knowledge-ask" id="knowledge-ask"><div><div class="eyebrow">ASK WITH EVIDENCE</div><h2>让好奇，有据可循。</h2><p>先找藏品与背景资料，再组织解释。可以点开引用，回到馆方核对。</p></div><div><form id="knowledge-question"><label for="knowledge-question-input">想问茶器的什么？</label><textarea id="knowledge-question-input" rows="3" maxlength="1200" placeholder="例如：喝茶为什么要用黑色的碗？">${e(question)}</textarea><div><button type="submit" class="solid-btn">查资料并解答 ↗</button><button type="button" data-knowledge-stop class="text-link" hidden>停止</button></div></form><div class="knowledge-prompts">${['宋代人怎么喝茶？','兔毫是画上去的吗？','包金属口沿是不是破了才修的？'].map(q=>`<button data-knowledge-question="${e(q)}">${e(q)}</button>`).join('')}</div><div id="knowledge-answer" aria-live="polite"></div></div></section>`}
 function steps(){return `<section class="section"><div class="section-head"><div class="section-title"><h2>从一口茶，读到一种生活</h2><span>A THREE-STEP READING</span></div></div><div class="knowledge-steps">${data.topics[0].steps.map((s,i)=>`<article><small>0${i+1} / 学习线索</small><h3>${e(s.title)}</h3><p>${e(s.text)}</p><div>${s.objects.map(id=>`<a href="#object/${id}">${e(get(id).title)} ↗</a>`).join('')}</div><details><summary>相关背景资料</summary>${s.documents.map(id=>{const d=data.documents.find(d=>d.id===id);return links(d.sourceIds)}).join('')}</details></article>`).join('')}</div></section>`}
 function documents(){return `<section class="section knowledge-documents"><div class="section-head"><div class="section-title"><h2>把器物，放回它的语境</h2><span>5 BACKGROUND READINGS</span></div></div>${data.documents.map((d,i)=>`<details><summary><small>0${i+1} · ${e(d.institution)}</small><strong>${e(d.title)}</strong><span>展开＋</span></summary><p>${e(d.summary)}</p><ul>${d.claims.map(c=>`<li>${e(c.text)}</li>`).join('')}</ul>${links(d.sourceIds)}<p class="tiny-note">观物整理摘要，非馆方全文转载。背景观点不等同于每一件器物的使用记录。</p></details>`).join('')}</section>`}
 function page(){return `<section class="knowledge-hero"><div class="knowledge-hero-copy"><div class="eyebrow">跨博物馆文化知识助手 · 第一期</div><span class="knowledge-issue">生活的考古 / 001</span><h1>从一盏茶，<br>读懂古人的<span>日常。</span></h1><p>器物不再是孤立的展签。<br>沿着用途、时代与手艺，<br>让不同博物馆的收藏相互照亮。</p><div><a class="solid-btn" href="#knowledge/ask">带着问题探索 ↗</a><a class="text-link" href="#knowledge-compare">自由对看 ↗</a></div><small>20 件茶器 · 3 家收藏机构 · 5 篇背景资料</small></div><div class="knowledge-hero-image">${image(get('tea-met-48117'),'fetchpriority="high"')}<span>不是一只普通的黑碗。<br><small>建窑兔毫茶盏 · 79.2.1358 · The Met · CC0</small></span></div></section>${steps()}${askPanel()}<section class="section"><div class="section-head"><div class="section-title"><h2>把不同收藏，放在同一张桌上</h2><span>THE OBJECT INDEX</span></div><a class="text-link" href="#knowledge/sources">资料与收录范围 ↗</a></div><div class="knowledge-filters"><label>想找什么<input type="search" id="knowledge-query" value="${e(filters.query)}" placeholder="兔毫、叶子、乾隆、藏品编号…"></label>${[['institution','收藏机构',[...new Set(data.objects.map(o=>o.institution))]],['period','年代',[...new Set(data.objects.map(o=>o.period))]],['objectType','器物类型',['茶盏','茶壶']]].map(([k,label,opts])=>`<label>${label}<select data-knowledge-filter="${k}"><option value="">全部</option>${opts.map(v=>`<option value="${e(v)}" ${filters[k]===v?'selected':''}>${e(v)}</option>`).join('')}</select></label>`).join('')}<button class="text-link" data-knowledge-reset>重置</button></div><div id="knowledge-results">${result()}</div></section>${documents()}<div class="knowledge-boundary"><strong>知识有边界，好奇可以继续。</strong><p>${e(data.scope)}资料核对日期：${data.updated}。未写明的编号、尺寸、用途与流传信息保持缺失。<a href="#knowledge/sources">查看来源与使用条件 ↗</a></p></div>`}
 function fieldRow(o,key){const f=o.fields[key];return `<div class="knowledge-field"><dt>${fieldLabels[key]}</dt><dd>${e(f.value??'当前整理来源未说明')} ${f.sourceIds.length?`<details><summary>出处 ↗</summary>${links(f.sourceIds)}</details>`:'<span class="knowledge-missing">留白，待补证</span>'}</dd></div>`}
 function detail(id){const o=get(id);if(!o)return '<h1>未收录这件茶器</h1><a href="#knowledge">返回专题</a>';const related=data.objects.filter(x=>x.id!==id&&(x.institution!==o.institution)&&(x.objectType===o.objectType)).slice(0,3);return `<div class="detail-breadcrumb"><a href="#knowledge">文化知识助手</a><span>/</span>藏品档案</div><section class="knowledge-object"><div class="knowledge-object-image">${image(o,'fetchpriority="high"')}<p>${e(o.image.rights)} ${o.image.policyUrl?`<a href="${e(o.image.policyUrl)}" target="_blank" rel="noopener">许可说明 ↗</a>`:''}</p>${links(o.sourceIds)}</div><div><div class="eyebrow">${e(o.institution)} · ${e(o.period)}</div><h1>${e(o.title)}</h1><p class="knowledge-object-lead">${e(o.summary)}</p><p class="tiny-note">观物依馆方资料整理；英文馆藏的中文名称为辅助译名。不是原文全文。</p><div class="knowledge-object-actions"><button class="solid-btn" data-knowledge-question="这件${e(o.title)}有哪些已确认的事实，哪些用途和信息还没有依据？">问问这件器物 ↗</button><button class="outline-btn" data-knowledge-pick="${o.id}">${selected.includes(id)?'✓ 已选入对看':'＋ 加入双件对看'}</button></div><dl>${Object.keys(fieldLabels).map(k=>fieldRow(o,k)).join('')}</dl></div></section>${o.dateViews.length?`<section class="knowledge-difference"><strong>同一来源，也可能保留不同表述</strong>${o.dateViews.map(v=>`<p>${e(v.label)}：${e(v.value)}</p>${links(v.sourceIds)}`).join('')}<p>这里并列原始说法，不替馆方作出统一断代。时代筛选使用整理归类，不能代替原始记录。</p></section>`:''}${relations(o)}${GuanwuObjectViewer.panel(o)}${bar()}${askPanel()}<section class="section">${head('换一座馆，继续看','CONNECTED BY A QUESTION')}<p class="tiny-note">下面按器物类别关联，表示可以比较，不代表具有直接流传关系。</p><div class="knowledge-grid">${related.map(card).join('')}</div></section>`}
 function relations(o){const edges=data.relations.filter(r=>r.fromId===o.id||r.toId===o.id);return edges.length?`<section class="section knowledge-relations"><div class="eyebrow">跨馆线索 · 每一种联系，也有依据</div>${edges.map(r=>{const other=get(r.fromId===o.id?r.toId:r.fromId);return `<article><h2>${e(r.title)}</h2><p>${e(r.text)}</p><a class="text-link" href="#object/${other.id}">${e(other.institution+' · '+other.title)} ↗</a><details><summary>这一联系的出处</summary>${links(r.sourceIds)}</details></article>`}).join('')}</section>`:''}
 function compare(){const pair=selected.map(get);return `<div class="detail-breadcrumb"><a href="#knowledge">茶器专题</a><span>/</span>双件对看</div><div class="intro"><div><div class="eyebrow">TWO OBJECTS, MANY QUESTIONS</div><h1>把差别，看得有据。</h1><p>对照年代、材质与用途。相似不是同一件，缺失也不等于相同。</p></div></div><div class="knowledge-compare-selectors">${[0,1].map(i=>`<label>第 ${i+1} 件<select data-knowledge-compare="${i}"><option value="">请选择茶器</option>${data.objects.map(o=>`<option value="${o.id}" ${selected[i]===o.id?'selected':''}>${e(o.institution+' · '+o.title+' · '+(o.fields.accession.value||'编号未提供'))}</option>`).join('')}</select></label>`).join('')}</div>${pair.length===2?`<div class="knowledge-compare-images">${pair.map(o=>`<a href="#object/${o.id}">${image(o)}<h2>${e(o.title)}</h2><small>${e(o.institution)}</small></a>`).join('')}</div><div class="knowledge-table-scroll"><table class="knowledge-table"><caption>两件茶器的馆方事实对照</caption><thead><tr><th scope="col">对照维度</th>${pair.map(o=>`<th scope="col">${e(o.title)}</th>`).join('')}</tr></thead><tbody>${['accession','dateOriginal','medium','dimensions','technique','use','provenance'].map(k=>`<tr><th scope="row">${fieldLabels[k]}</th>${pair.map(o=>`<td>${e(o.fields[k].value??'当前来源未说明')}<div>${links(o.fields[k].sourceIds)}</div></td>`).join('')}</tr>`).join('')}</tbody></table></div><p class="tiny-note">表格是事实并置，不证明器物之间有直接历史关系。缺失字段不推算，年代原文不擅自合并。</p>${askPanel('这两件茶器在年代、材质、工艺和用途上有什么不同？请分别给出出处。')}`:'<div class="soft-empty">选两件不同的茶器，开启对看。<button class="text-link" data-knowledge-example>试试：故宫兔毫盏 × 上博木叶盏 ↗</button></div>'}`}
 function sourcesPage(){return `<div class="detail-breadcrumb"><a href="#knowledge">茶器专题</a><span>/</span>资料与范围</div><div class="intro"><div><div class="eyebrow">EVERY FACT HAS A SOURCE</div><h1>让每一条线索，可以核对。</h1><p>${e(data.scope)}</p></div></div><div class="knowledge-boundary"><strong>文字使用条件与图片使用条件，分别记录。</strong><p>公开可访问不等于授权转载或商用。本文不复制馆方全文；未确认展示许可的图片只提供原站入口。CC0 只对应逐件核对的开放图片，不适用于该馆全部网页。</p><a href="https://www.chnmuseum.cn/shxg/bqsm/201901/t20190102_37015.shtml" target="_blank" rel="noopener">国博版权声明 ↗</a> · <a href="https://www.si.edu/openaccess/faq" target="_blank" rel="noopener">史密森尼开放资源边界 ↗</a></div><section class="section"><h2>茶器专题 · 来源台账</h2><div class="knowledge-source-list">${data.sources.map(s=>`<details><summary>${e(s.title)}<span>${s.kind==='background'?'背景资料':'藏品资料'}</span></summary><p>核对日期：${s.checkedAt}</p><p>文字：${e(s.textRights)}</p><p>图片：${e(data.objects.find(o=>o.sourceIds.includes(s.id))?.image.rights||'未转载原文配图。')}</p>${links([s.id])}</details>`).join('')}</div></section><section class="section"><h2>已有 ${museums.length} 家博物馆 · 收录深度</h2><p>所有场馆保留现有馆级导览与官方入口；茶器档案按具体文物逐件深化。下列“馆级导览”不代表已整理该馆全部公开资料。</p><div class="knowledge-museum-directory">${museums.map(m=>{const count=data.objects.filter(o=>o.museum===m.id).length;return `<article><a href="#museum/${m.id}">${e(m.name)} ↗</a><span>${e(m.city)} · ${count?'茶器档案 '+count+' 件':'馆级导览'}</span><a href="${e(m.official)}" target="_blank" rel="noopener">官方入口 ↗</a></article>`}).join('')}</div></section>`}
 function context(){const [kind,id]=location.hash.slice(1).split('/');if(kind==='object'&&get(id))return{id,name:get(id).title};if(kind==='knowledge-compare')return{id:'knowledge-compare:'+selected.join(','),name:'茶器双件对看'};if(kind==='knowledge')return{id:'knowledge:tea',name:'古代饮茶与茶器 · 跨馆知识专题'};return null}
 function citationText(text,evidence){const allowed=new Map(evidence.sources.map(s=>[s.id,s]));return e(text).replace(/\[([^\]]+)\]/g,(_,id)=>{const s=allowed.get(id);return s?`<a class="knowledge-citation" href="${e(s.url)}" target="_blank" rel="noopener">〔${e(s.institution)}·出处〕</a>`:e('['+id+']')}).replace(/\n/g,'<br>')}
 async function ask(question){if(controller)return;const box=document.getElementById('knowledge-answer');if(!box)return;const form=document.getElementById('knowledge-question'),input=document.getElementById('knowledge-question-input');input.value=question;form.querySelector('[type=submit]').disabled=true;form.querySelector('[data-knowledge-stop]').hidden=false;box.innerHTML='<p role="status">正在查找藏品与背景资料，再组织解释…</p>';controller=new AbortController();const [kind,id]=location.hash.slice(1).split('/'),ids=kind==='object'?[id]:kind==='knowledge-compare'?selected:[];try{const r=await fetch('/api/knowledge/ask',{method:'POST',headers:{'Content-Type':'application/json'},signal:controller.signal,body:JSON.stringify({question,filters,ids})}),d=await r.json(),proof=d.evidence?`<details class="knowledge-retrieved"><summary>本次找到了什么？${d.evidence.objects.length} 件藏品 · ${d.evidence.documents.length} 篇背景</summary>${d.evidence.objects.map(o=>`<a href="#object/${o.id}">${e(o.title)} · ${e(o.institution)} ↗</a>`).join('')}${d.evidence.sources.map(s=>`<a href="${e(s.url)}" target="_blank" rel="noopener">${e(s.title)} ↗</a>`).join('')}</details>`:'';if(!r.ok){box.innerHTML=`<p class="knowledge-error">${e(d.error)}</p><button class="text-link" data-knowledge-retry>重试讲解 ↗</button>${proof}`;return}const a=d.answer;box.innerHTML=`<article class="knowledge-response"><small>${d.mode==='source_grounded'?'依据本次检索资料生成 · DeepSeek':'本次证据不足'}</small><h3>简明解释</h3><p>${citationText(a.explanation,d.evidence)}</p><h3>对应藏品</h3>${a.objects.map(o=>`<p><a href="#object/${e(o.id)}">${e(get(o.id)?.title||o.id)} ↗</a><br>${citationText(o.reason,d.evidence)}</p>`).join('')||'<p>未能确定具体藏品。</p>'}<h3>背景说明</h3><p>${citationText(a.background,d.evidence)}</p><div class="knowledge-boundary"><strong>还不能确定的部分</strong><p>${citationText(a.uncertainty,d.evidence)}</p></div></article>${proof}`;}catch(err){box.innerHTML=`<p>${err.name==='AbortError'?'已停止本次讲解。':'连接暂时中断，请重试。'}</p><button class="text-link" data-knowledge-retry>重试讲解 ↗</button>`}finally{controller=null;form.querySelector('[type=submit]').disabled=false;form.querySelector('[data-knowledge-stop]').hidden=true}}
 function update(){document.getElementById('knowledge-results').innerHTML=result()}
 function saveSelection(){try{localStorage.setItem('guanwu-tea-compare',JSON.stringify(selected))}catch{}document.querySelectorAll('[data-knowledge-pick]').forEach(b=>{const yes=selected.includes(b.dataset.knowledgePick);b.setAttribute('aria-pressed',yes);b.textContent=yes?'✓ 已选':'＋ 对看'});const b=document.querySelector('.knowledge-compare-bar');if(b)b.outerHTML=bar()}
 document.addEventListener('input',ev=>{if(ev.target.id==='knowledge-query'){filters.query=ev.target.value;update()}});
 document.addEventListener('change',ev=>{if(ev.target.dataset.knowledgeFilter){filters[ev.target.dataset.knowledgeFilter]=ev.target.value;update()}if(ev.target.dataset.knowledgeCompare!==undefined){const index=Number(ev.target.dataset.knowledgeCompare),id=ev.target.value;if(id&&selected.some((x,i)=>i!==index&&x===id)){toast('请选两件不同的茶器。');ev.target.value=selected[index]||'';return}selected[index]=id;selected=selected.filter(Boolean);saveSelection();render(false)}});
 document.addEventListener('submit',ev=>{if(ev.target.id==='knowledge-question'){ev.preventDefault();const v=document.getElementById('knowledge-question-input').value.trim();if(v)ask(v)}});
 document.addEventListener('click',ev=>{const b=ev.target.closest('button');if(!b)return;if(b.dataset.knowledgePick){const id=b.dataset.knowledgePick;if(selected.includes(id))selected=selected.filter(x=>x!==id);else if(selected.length<2)selected.push(id);else{toast('已选两件，先移除一件再更换。');return}saveSelection()}if(b.hasAttribute('data-knowledge-clear')){selected=[];saveSelection()}if(b.hasAttribute('data-knowledge-reset')){filters={query:'',institution:'',period:'',objectType:''};render(false)}if(b.hasAttribute('data-knowledge-example')){selected=['tea-dpm-227128','tea-sh-leaf'];saveSelection();render(false)}if(b.dataset.knowledgeQuestion){document.getElementById('knowledge-ask')?.scrollIntoView({behavior:'smooth',block:'start'});ask(b.dataset.knowledgeQuestion)}if(b.hasAttribute('data-knowledge-stop'))controller?.abort();if(b.hasAttribute('data-knowledge-retry'))ask(document.getElementById('knowledge-question-input').value.trim())});
 window.addEventListener('hashchange',()=>controller?.abort());
 function mount(route){GuanwuObjectViewer.mount(route);if(route==='knowledge/ask')requestAnimationFrame(()=>document.getElementById('knowledge-ask')?.scrollIntoView({block:'start'}))}
 function museumSection(id){const found=data.objects.filter(o=>o.museum===id);return found.length?`<section class="section">${head('从这座馆，走进茶器生活','SOURCED OBJECT RECORDS','#knowledge','跨馆继续探索')}<p class="tiny-note">${found.length} 件已核对的茶器档案，保留用途、年代与逐字段出处；收藏不等于当前展出。</p><div class="knowledge-grid">${found.map(card).join('')}</div></section>`:''}
 return {page,detail,compare,sourcesPage,teaser,context,mount,get,museumSection};
})();
